function calculateTotal(price: number, taxRate: number) {
  const taxAmount = price * taxRate;
  return price + taxAmount;
}

const total = calculateTotal(100, 0.08);
console.log(`Total: $${total}`); // Output: Total: $108

function isAdult(age: number): boolean {
  if (age < 0) {
    throw new Error("Age cannot be negative");
  }
  return age >= 18;
}

const allowed: boolean = isAdult(21);
console.log(`Access permitted: ${allowed}`);

function greetUser(name: string, greeting: string = "Hello", title?: string): string {
  if (title) {
    return `${greeting}, ${title} ${name}!`;
  }
  return `${greeting}, ${name}!`;
}

console.log(greetUser("Alice")); // Hello, Alice!
console.log(greetUser("Bob", "Welcome")); // Welcome, Bob!
console.log(greetUser("Smith", "Good morning", "Dr.")); // Good morning, Dr. Smith!

function sumAll(...numbers: number[]): number {
  return numbers.reduce((accumulator, current) => accumulator + current, 0);
}

console.log(sumAll(10, 20, 30)); // 60
console.log(sumAll(5, 15, 25, 35, 45)); // 125
console.log(sumAll()); // 0

function registerStudent(student: { name: string; grade: number; email?: string }): string {
  const contactInfo = student.email ? ` (Email: ${student.email})` : "";
  return `Registered ${student.name} in Grade ${student.grade}${contactInfo}`;
}

const studentA = { name: "Sophia", grade: 10 };
const studentB = { name: "Liam", grade: 12, email: "liam@school.edu" };

console.log(registerStudent(studentA));
console.log(registerStudent(studentB));

// 'void' indicates a function returns nothing (or returns undefined)
function logSystemMessage(message: string): void {
  console.log(`[LOG]: ${message}`);
  // Implicitly returns undefined
}

// 'never' indicates a function NEVER completes or returns an endpoint
// (e.g. throws an exception or runs an infinite event loop)
function throwFatalError(errorMessage: string): never {
  throw new Error(`Fatal system crash: ${errorMessage}`);
}

function infiniteMonitorLoop(): never {
  while (true) {
    // Background service daemon loop that never terminates
  }
}
